-- =============================================================================
-- PVK CINEMAS — V11__phase1a_physical_dataset.sql
-- Part 1A: Physical Cinema Ecosystem Realism Master Dataset
-- Dataset Version : 2026.10
-- Deterministic Seed: PVK-PHASE1-SEED-42
-- Target: 5 Cities | 25 Theatres | 127 Screens | 16,386 Seats
-- Heterogeneous Auditoriums (3–8 per theatre, 64–240 seats per screen)
-- Operating Hours, Theatre Tiers, and Screen Premium Flags
-- =============================================================================

SET FOREIGN_KEY_CHECKS = 0;

-- -----------------------------------------------------------------------------
-- 1. ORDERED CLEANUP OF OBSOLETE DEMO OPERATIONAL & MASTER DATA
-- -----------------------------------------------------------------------------
-- Existing V5/V8 mock show inventory (5,000 shows, 600,000 show seats, 2 demo bookings)
-- was bound to the legacy uniform layout (125 screens, 120 seats/screen).
-- In Part 1A, screen counts per theatre vary (3 to 8), screen capacities vary (64 to 240),
-- and physical seat IDs shift. Preserving old show seats would corrupt physical integrity
-- (shows referencing seats on different physical screens).
-- Phase 1A establishes authoritative Category A physical master data.
-- Operational show inventory is generated in Part 3 (V13).
DELETE FROM SEAT_HOLD;
ALTER TABLE SEAT_HOLD AUTO_INCREMENT = 1;

DELETE FROM PAYMENT;
ALTER TABLE PAYMENT AUTO_INCREMENT = 1;

DELETE FROM BOOKING_SEAT;
ALTER TABLE BOOKING_SEAT AUTO_INCREMENT = 1;

DELETE FROM BOOKING;
ALTER TABLE BOOKING AUTO_INCREMENT = 1;

DELETE FROM SHOW_SEAT;

DELETE FROM `SHOW`;
ALTER TABLE `SHOW` AUTO_INCREMENT = 1;

DELETE FROM SEAT;
ALTER TABLE SEAT AUTO_INCREMENT = 1;

DELETE FROM SCREEN_CAPABILITY;
ALTER TABLE SCREEN_CAPABILITY AUTO_INCREMENT = 1;

DELETE FROM SCREEN;
ALTER TABLE SCREEN AUTO_INCREMENT = 1;

SET FOREIGN_KEY_CHECKS = 1;

-- -----------------------------------------------------------------------------
-- 2. THEATRE OPERATING HOURS & VENUE TIERS (Part 1A / Part 3 Specification)
-- -----------------------------------------------------------------------------
-- FLAGSHIP (6 venues): 08:30:00 to 01:30:00 (+1 day) = 17.0 hours
-- BOUTIQUE (5 venues): 10:00:00 to 23:00:00         = 13.0 hours
-- SUBURBAN (14 venues): 09:30:00 to 23:45:00        = 14.25 hours

UPDATE THEATRE
SET theatre_tier = 'FLAGSHIP', opening_time = '08:30:00', closing_time = '01:30:00'
WHERE theatre_code IN (
    'DEMO_BLR_CINEPLEX',
    'DEMO_BOM_CINEPLEX',
    'DEMO_CHN_CINEPLEX',
    'DEMO_DEL_CINEPLEX',
    'DEMO_HYD_CINEPLEX',
    'DEMO_HYD_PRASADS'
);

UPDATE THEATRE
SET theatre_tier = 'BOUTIQUE', opening_time = '10:00:00', closing_time = '23:00:00'
WHERE theatre_code IN (
    'DEMO_BLR_SPI',
    'DEMO_BOM_PVR',
    'DEMO_CHN_SPI',
    'DEMO_DEL_INOX',
    'DEMO_DEL_PVR'
);

UPDATE THEATRE
SET theatre_tier = 'SUBURBAN', opening_time = '09:30:00', closing_time = '23:45:00'
WHERE theatre_code IN (
    'DEMO_BLR_AGS',
    'DEMO_BLR_INOX',
    'DEMO_BLR_PVR',
    'DEMO_BOM_AGS',
    'DEMO_BOM_INOX',
    'DEMO_BOM_METRO',
    'DEMO_CHN_AGS',
    'DEMO_CHN_INOX',
    'DEMO_CHN_PVR',
    'DEMO_DEL_AGS',
    'DEMO_DEL_METRO',
    'DEMO_HYD_AMB',
    'DEMO_HYD_INOX',
    'DEMO_HYD_PVR'
);

-- -----------------------------------------------------------------------------
-- 3. RESOLVE REFERENCE DATA NATURAL IDENTIFIERS
-- -----------------------------------------------------------------------------
SET @pf_2d    = (SELECT presentation_format_id FROM PRESENTATION_FORMAT WHERE format_code = '2D');
SET @pf_3d    = (SELECT presentation_format_id FROM PRESENTATION_FORMAT WHERE format_code = '3D');
SET @pf_imax  = (SELECT presentation_format_id FROM PRESENTATION_FORMAT WHERE format_code = 'IMAX');
SET @pf_4dx   = (SELECT presentation_format_id FROM PRESENTATION_FORMAT WHERE format_code = '4DX');

SET @af_5_1   = (SELECT audio_format_id FROM AUDIO_FORMAT WHERE format_code = 'DOLBY_5_1');
SET @af_7_1   = (SELECT audio_format_id FROM AUDIO_FORMAT WHERE format_code = 'DOLBY_7_1');
SET @af_atmos = (SELECT audio_format_id FROM AUDIO_FORMAT WHERE format_code = 'DOLBY_ATMOS');
SET @af_imax  = (SELECT audio_format_id FROM AUDIO_FORMAT WHERE format_code = 'IMAX_12CH');

SET @st_std   = (SELECT seat_type_id FROM SEAT_TYPE WHERE type_code = 'STANDARD');
SET @st_prem  = (SELECT seat_type_id FROM SEAT_TYPE WHERE type_code = 'PREMIUM');
SET @st_rec   = (SELECT seat_type_id FROM SEAT_TYPE WHERE type_code = 'RECLINER');
SET @st_acc   = (SELECT seat_type_id FROM SEAT_TYPE WHERE type_code = 'ACCESSIBLE');

